async function handleFbtqAssistantMessageAction(event){const confirmButton=event.target.closest('[data-assistant-workflow-confirm]');if(confirmButton){confirmButton.disabled=true;const requested=JSON.parse(confirmButton.dataset.assistantWorkflowConfirm||'{}'),payload=fbtqPendingConfirmation||{};if(!fbtqPendingConfirmation||requested.nonce!==payload.nonce||payload.actorUid!==state.user?.uid||Date.now()-payload.issuedAt>300000){appendFbtqAssistantMessage('assistant','Xác nhận này đã hết hiệu lực. Hãy kiểm tra lại danh sách và gửi lệnh mới.',[],event.currentTarget);return}fbtqPendingConfirmation=null;try{let result;if(payload.actionType==='workflow')result=await workflows.assistantReview(payload.kind,payload.id,payload.decision,payload.note);else if(payload.actionType==='invoice'){const ok=await updateInvoiceStatus(payload.id,payload.decision==='approve'?'approved':'rejected',payload.note);if(!ok)throw new Error('Không cập nhật được hóa đơn. Hãy kiểm tra quyền và trạng thái hiện tại.');result={title:'Hóa đơn',status:payload.decision==='approve'?'approved':'rejected'}}else if(payload.actionType==='content-review')result=await applyFbtqContentReview(payload.id,payload.decision,payload.note);else if(payload.actionType==='task-status'){const task=state.tasks.find(item=>item.id===payload.id);if(!task)throw new Error('Không tìm thấy công việc. Hãy tải lại danh sách.');if(!isManager()&&task.assigneeUid!==state.user?.uid&&task.assignee!==state.user?.name)throw new Error('Bạn không còn quyền cập nhật công việc này.');const now=new Date().toISOString(),updated={...task,status:payload.status,completedAt:payload.status==='done'?now:null,updatedAt:now};await saveRecord('tasks',updated,updated.id);state.tasks=state.tasks.map(item=>item.id===updated.id?updated:item);saveLocal();renderTasks($('[data-task-filter].selected')?.dataset.taskFilter||'all');result={id:updated.id,title:updated.title,status:updated.status}}else throw new Error('Loại xác nhận không được hỗ trợ.');fbtqPendingConfirmation=null;const status=result.status==='pending'?'Đã duyệt bước '+(result.stageName||'đầu tiên')+'; hồ sơ vẫn chờ cấp duyệt tiếp theo.':result.status==='revision_requested'?'Đã gửi lại bài viết để chỉnh sửa.':result.status==='rejected'?'Đã ghi nhận từ chối.':payload.actionType==='task-status'?'Đã cập nhật trạng thái công việc.':'Đã ghi nhận phê duyệt.';appendFbtqAssistantMessage('assistant',`${status} Hồ sơ: ${result.title||'Hồ sơ'} · mã …${String(result.id||payload.id).slice(-8)}.`,[],event.currentTarget)}catch(error){confirmButton.disabled=false;appendFbtqAssistantMessage('assistant',error?.message||'Không thể hoàn tất thao tác. Hãy tải lại danh sách.',[],event.currentTarget)}return}const cancelButton=event.target.closest('[data-assistant-workflow-cancel]');if(cancelButton){if(fbtqPendingConfirmation?.nonce===cancelButton.dataset.assistantWorkflowCancel){fbtqPendingConfirmation=null;cancelButton.disabled=true;appendFbtqAssistantMessage('assistant','Đã hủy. Hồ sơ chưa bị thay đổi.',[],event.currentTarget)}return}const copy=event.target.closest('[data-assistant-copy]');if(copy){try{await navigator.clipboard.writeText(copy.dataset.assistantCopy||'');showToast('Đã sao chép nội dung.')}catch{showToast('Không thể sao chép. Hãy chọn và sao chép nội dung thủ công.','error')}return}const navigateAction=event.target.closest('[data-assistant-navigate]');if(navigateAction){setFbtqAssistantWindow(false);navigate(navigateAction.dataset.assistantNavigate);return}const openStudio=event.target.closest('[data-assistant-open-studio]');if(openStudio){setFbtqAssistantWindow(false);navigate('content');const prompt=$('#contentPrompt');if(prompt){prompt.value=openStudio.dataset.assistantPrompt||'';prompt.focus()}}}
