function safeAvatarPhoto(photoData){return typeof photoData==='string'&&photoData.length<=180000&&/^data:image\/jpeg;base64,[A-Za-z0-9+/]+={0,2}$/.test(photoData)?photoData:''}
function avatarMarkup(photoData,initials,className='avatar avatar-blue'){const photo=safeAvatarPhoto(photoData);return photo?'<span class="'+className+' avatar-photo"><img src="'+photo+'" alt="Ảnh đại diện" loading="lazy"></span>':'<span class="'+className+'">'+esc(initials||'NV')+'</span>'}
function setAvatarElement(element,photoData,initials){if(!element)return;const safePhoto=safeAvatarPhoto(photoData);element.replaceChildren();element.classList.toggle('avatar-photo',!!safePhoto);if(safePhoto){const image=document.createElement('img');image.src=safePhoto;image.alt='Ảnh đại diện';element.append(image)}else element.textContent=initials||'NV'}
