function assignMetricIds(rows){const counts=new Map();rows.forEach(row=>{if(!row.sourceKey)counts.set(row.baseKey,(counts.get(row.baseKey)||0)+1)});return rows.map(row=>{if(row.sourceKey&&row.id)return row;const sourceKey=row.sourceKey||row.baseKey+(counts.get(row.baseKey)>1?'|variant:'+row.variantKey:'');return{...row,id:'metric-'+stableMetricHash(sourceKey),sourceKey}})}
function metricCount(value){return value===null||value===undefined||value===''?'—':Number(value).toLocaleString('vi-VN')}
function metricMoney(value){return value===null||value===undefined||value===''?'—':money(value)}
