function campaignOwner(c){const uid=String(c.createdBy||'');const profile=state.users.find(user=>user.uid===uid);if(profile)return{name:profile.name||profile.email||'Tài khoản',detail:profile.email||'Tài khoản thành viên',photoData:profile.photoData||''};if(c.createdByName)return{name:c.createdByName,detail:c.createdByEmail||'Người nhập dữ liệu',photoData:''};return uid?{name:'Tài khoản thành viên',detail:'UID: '+uid.slice(0,12)+(uid.length>12?'…':''),photoData:''}:{name:'Chưa xác định',detail:'Bản ghi chưa có thông tin người tạo',photoData:''}}
function campaignOwnerCell(c){const owner=campaignOwner(c),initial=String(owner.name||'U').trim().slice(0,1).toUpperCase();return'<td>'+avatarMarkup(owner.photoData,initial,'campaign-avatar ca-blue')+'<span class="campaign-title"><b>'+esc(owner.name)+'</b><small>'+esc(owner.detail)+'</small></span></td>'}
