function campaignRows(list,showOwner=false){return list.map(c=>'<tr><td><span class="campaign-avatar '+(String(c.platform).toLowerCase().includes('google')?'ca-yellow':'ca-blue')+'">'+esc(String(c.name||'?').slice(0,1).toUpperCase())+'</span><span class="campaign-title"><b>'+esc(c.name)+'</b><small>'+esc(c.account)+'</small></span></td>'+(showOwner?campaignOwnerCell(c):'')+'<td><span class="status '+(c.status==='Đang chạy'?'status-live':'status-review')+'">● '+esc(c.status||c.delivery||'—')+'</span></td><td>'+esc(reportPeriodLabel(c))+'</td><td>'+metricMoney(c.budget)+'<small>'+esc(c.budgetType||'')+'</small></td><td>'+metricMoney(c.spend)+'</td><td>'+metricCount(c.impressions)+'</td><td>'+metricCount(c.reach)+'</td><td>'+metricCount(c.results)+'<small>'+esc(c.resultIndicator||'')+'</small></td><td>'+metricMoney(c.costPerResult)+'</td><td>'+metricCount(c.newMessagingContacts)+'</td><td>'+metricMoney(c.costPerNewMessagingContact)+'</td><td>'+metricCount(c.messagingConversationsStarted)+'</td><td>'+metricMoney(c.costPerMessagingConversationStart)+'</td><td>'+(c.roas===null||c.roas===undefined?'—':'<b>'+Number(c.roas).toFixed(2)+'x</b>')+'</td><td><details class="metric-more"><summary>Chi tiết</summary><dl>'+detailItem('Cài đặt ghi nhận',c.attributionSetting)+detailItem('Bắt đầu nhóm',c.adSetStart)+detailItem('Kết thúc nhóm',c.adSetEnd)+detailItem('Giá thầu',c.bid)+detailItem('Loại giá thầu',c.bidType)+detailItem('Sửa đổi gần nhất',c.lastSignificantEdit)+detailItem('Kết quả ban đầu',c.originalResults)+detailItem('Chỉ báo ban đầu',c.originalResultIndicator)+(c.rawColumns||[]).map(column=>detailItem(column.label,column.value)).join('')+'</dl></details></td></tr>').join('')}
function renderBarChart(targetId,labelId,list,periodLabel){
  const bars=$('#'+targetId),label=$('#'+labelId);
  if(!bars||!label)return;
  const ordered=[...list].sort((a,b)=>(Number(b.spend)||0)-(Number(a.spend)||0)).slice(0,12);
  bars.classList.add('metric-chart-host');
  if(!ordered.length){
    label.textContent='Chưa có số liệu trong kỳ này.';
    bars.innerHTML='<p class="muted chart-empty">Nhập CSV ở mục Hiệu suất marketing để xem biểu đồ.</p>';
    return;
  }
  label.textContent=periodLabel+' · trục trái: chi tiêu (₫) / kết quả (lượt), mỗi chỉ số có thang riêng; rê chuột hoặc chạm vào cột để xem số gốc';
  const maxSpend=Math.max(0,...ordered.map(item=>Number(item.spend)||0));
  const maxResults=Math.max(0,...ordered.map(item=>Number(item.results)||0));
  const compactSpend=value=>{const amount=Math.round(Number(value)||0);if(amount>=1e9)return(amount/1e9).toLocaleString('vi-VN',{maximumFractionDigits:1})+' tỷ ₫';if(amount>=1e6)return(amount/1e6).toLocaleString('vi-VN',{maximumFractionDigits:1})+' triệu ₫';if(amount>=1e3)return(amount/1e3).toLocaleString('vi-VN',{maximumFractionDigits:1})+' nghìn ₫';return amount.toLocaleString('vi-VN')+' ₫'};
  const axis=[100,75,50,25,0].map(value=>`<span title="${esc(money(maxSpend*value/100))} · ${esc(metricCount(Math.round(maxResults*value/100)))} lượt"><small class="bar-axis-spend">${esc(compactSpend(maxSpend*value/100))}</small><small class="bar-axis-results">${esc(metricCount(Math.round(maxResults*value/100)))}</small></span>`).join('');
  const grid='<i></i><i></i><i></i><i></i><i></i>';
  const groups=ordered.map((item,index)=>{
    const spend=Number(item.spend)||0,results=Number(item.results)||0;
    const name=String(item.name||'Nhóm quảng cáo'),resultType=String(item.resultIndicator||'Kết quả');
    const owner=isManager()?campaignOwner(item).name:'';
    const detail=`${name}${owner?' · Người phụ trách: '+owner:''} · Chi tiêu ${money(spend)} · ${resultType}: ${metricCount(item.results)}`;
    const spendHeight=maxSpend?spend/maxSpend*100:0,resultHeight=maxResults?results/maxResults*100:0;
    return `<div class="bar-group" tabindex="0" role="group" aria-label="${esc(detail)}" title="${esc(detail)}" style="--bar-delay:${index*35}ms">
      <div class="metric-chart-tooltip" role="tooltip"><b>${esc(name)}</b>${owner?`<small>Người phụ trách: ${esc(owner)}</small>`:''}<span><i class="legend-spend"></i>Chi tiêu <strong>${esc(money(spend))}</strong></span><span><i class="legend-revenue"></i>${esc(resultType)} <strong>${esc(metricCount(item.results))}</strong></span></div>
      <i class="bar spend" aria-label="Chi tiêu ${esc(money(spend))}" style="--bar-height:${spendHeight}%;animation-delay:${index*35}ms"></i>
      <i class="bar revenue" aria-label="${esc(resultType)} ${esc(metricCount(item.results))}" style="--bar-height:${resultHeight}%;animation-delay:${index*35+75}ms"></i>
    </div>`;
  }).join('');
  const labels=ordered.map(item=>`<span title="${esc(item.name||'Nhóm quảng cáo')}">${esc(item.name||'Nhóm quảng cáo')}</span>`).join('');
  bars.innerHTML=`<div class="metric-chart"><div class="bar-y-axis" aria-label="Chi tiêu và kết quả">${axis}</div><div class="bar-chart-main"><div class="bar-plot"><div class="bar-gridlines" aria-hidden="true">${grid}</div><div class="bar-columns">${groups}</div></div><div class="bar-x-axis" aria-label="Tên nhóm quảng cáo" style="grid-template-columns:repeat(${ordered.length},minmax(0,1fr))">${labels}</div></div></div>`;
}
function renderCampaignChart(list,periodLabel){renderBarChart('bigBars','chartReportLabel',list,periodLabel)}
function overviewProfile(uid){return state.users.find(user=>user.uid===uid)||(state.user?.uid===uid?state.user:null)}
function overviewBranchKey(profile){const value=String(profile?.branch||profile?.branchName||profile?.branchId||'').trim();return value?value.toLocaleLowerCase('vi-VN'):'__unassigned__'}
function overviewBranchLabel(profile){const value=String(profile?.branch||profile?.branchName||profile?.branchId||'').trim();return value||'Chưa gán chi nhánh'}
function overviewScopeUsers(){const available=state.users.filter(user=>user.approved!==false);if(state.user&&!available.some(user=>user.uid===state.user.uid))available.push(state.user);if(isDirector())return available;if(!isManager())return state.user?[state.user]:[];const own=overviewProfile(state.user?.uid)||state.user,branch=overviewBranchKey(own);return branch==='__unassigned__'?[own]:available.filter(user=>overviewBranchKey(user)===branch)}
function overviewMetricOwner(item){return overviewProfile(item.createdBy)||{uid:item.createdBy||'',name:item.createdByName||'',department:item.department||''}}
function metricOverlapsRange(item,range){const start=String(item.reportStart||item.reportAt||item.reportEnd||'').slice(0,10),end=String(item.reportEnd||item.reportAt||item.reportStart||'').slice(0,10);return(!range.start||!end||end>=range.start)&&(!range.end||!start||start<=range.end)}
function overviewMonthRange(monthKey){const [year,month]=monthKey.split('-').map(Number);if(!year||!month)return revenueWindowForMetrics([]);return{start:`${year}-${String(month).padStart(2,'0')}-01`,end:`${year}-${String(month).padStart(2,'0')}-${String(new Date(year,month,0).getDate()).padStart(2,'0')}`}}
function overviewMonthLabel(monthKey){const [year,month]=monthKey.split('-').map(Number);return new Intl.DateTimeFormat('vi-VN',{month:'long',year:'numeric'}).format(new Date(year,month-1,1))}
function renderOverviewMetrics(list,periodLabel,revenue,showCompanyRevenue=false){const spend=list.reduce((n,x)=>n+(Number(x.spend)||0),0),impressions=list.reduce((n,x)=>n+(Number(x.impressions)||0),0),reach=list.reduce((n,x)=>n+(Number(x.reach)||0),0),results=list.reduce((n,x)=>n+(Number(x.results)||0),0),hasResults=list.some(x=>x.results!==null&&x.results!==undefined);$('#overviewSpend').textContent=list.length?money(spend):'—';$('#overviewImpressions').textContent=list.length?impressions.toLocaleString('vi-VN'):'—';$('#overviewReach').textContent=list.length?reach.toLocaleString('vi-VN'):'—';$('#overviewResults').textContent=hasResults?results.toLocaleString('vi-VN'):'—';$('#overviewRevenue').textContent=money(revenue);$('#overviewRevenuePeriod').textContent=showCompanyRevenue?'Toàn công ty · '+periodLabel:periodLabel;$('#overviewPeriodLabel').textContent=periodLabel;$('#overviewPeriodLabelCopy').textContent=periodLabel;$('#overviewGroupCount').textContent=list.length?list.length+' nhóm quảng cáo':'Chưa có dữ liệu';$('#overviewPeriodSummary').textContent=periodLabel;$('#overviewGroupCountSummary').textContent=list.length?list.length+' nhóm quảng cáo':'0 nhóm quảng cáo';$('#overviewResultSummary').textContent=hasResults?results.toLocaleString('vi-VN')+' kết quả':'Chưa có kết quả được ghi nhận';renderBarChart('overviewBars','overviewReportLabel',list,periodLabel)}
function reportDateKey(report){if(/^\d{4}-\d{2}-\d{2}$/.test(String(report.reportDate||'')))return report.reportDate;const raw=report.submittedAt;if(!raw)return'';const date=raw?.toDate?raw.toDate():new Date(raw);if(Number.isNaN(date.getTime()))return'';return date.getFullYear()+'-'+String(date.getMonth()+1).padStart(2,'0')+'-'+String(date.getDate()).padStart(2,'0')}
function revenueWindowForMetrics(list){const valid=value=>/^\d{4}-\d{2}-\d{2}$/.test(String(value||''));const starts=list.map(item=>item.reportStart).filter(valid).sort(),ends=list.map(item=>item.reportEnd).filter(valid).sort();if(starts.length||ends.length){const all=[...starts,...ends].sort(),start=starts[0]||all[0],end=ends[ends.length-1]||all[all.length-1];return{start,end}}const points=list.map(item=>item.reportAt).filter(valid).sort();if(points.length)return{start:points[0],end:points[points.length-1]};const now=new Date(),start=now.getFullYear()+'-'+String(now.getMonth()+1).padStart(2,'0')+'-01',end=now.getFullYear()+'-'+String(now.getMonth()+1).padStart(2,'0')+'-'+String(new Date(now.getFullYear(),now.getMonth()+1,0).getDate()).padStart(2,'0');return{start,end}}
function revenueForCampaignPeriod(list,ownerUid='all'){const range=revenueWindowForMetrics(list),entries=state.revenueEntries.length?state.revenueEntries:state.dailyReports;return entries.filter(report=>{const date=reportDateKey(report),ownerMatches=ownerUid==='all'||!ownerUid||report.createdBy===ownerUid;return ownerMatches&&date&&date>=range.start&&date<=range.end}).reduce((total,report)=>total+(Number(report.revenue)||0),0)}
function renderOverviewOperations(){overviewHub?.render(overviewHubContext);}
