function showGenerated(title,text){const panel=$('#resultPanel');panel.setAttribute('aria-live','polite');panel.innerHTML=`<div class="result-generated"><div class="generated-head"><div class="generated-title"><span class="result-ai-mark">✦</span><b>Phản hồi AI</b></div><span class="status status-neutral">BẢN NHÁP</span></div><div class="generated-prompt-label">${esc(title)}</div><div class="generated-content" contenteditable="true" aria-label="Nội dung do AI tạo">${esc(text)}</div><div class="generated-actions"><button class="btn btn-secondary" id="saveDraft">▤ Lưu nháp</button><button class="btn btn-secondary" id="copyContent">▣ Sao chép</button><button class="btn btn-secondary" id="sendToSpeech">🔊 Tạo giọng đọc</button><button class="btn btn-primary manager-review">⇧ Gửi kiểm duyệt</button></div></div>`;$('#saveDraft').addEventListener('click',()=>saveDraft(title,$('.generated-content').innerText));$('#copyContent').addEventListener('click',async()=>{try{await navigator.clipboard.writeText($('.generated-content').innerText);showToast('Đã sao chép nội dung.')}catch{showToast('Trình duyệt chưa cho phép clipboard.','error')}});$('#sendToSpeech').addEventListener('click',()=>{const content=$('.generated-content').innerText;$('#speechText').value=content;updateSpeechCount();$$('[data-editor-tab]').find(x=>x.dataset.editorTab==='speech').click();$('#speechText').focus();showToast('Đã chuyển bản nháp sang tab Giọng đọc trong Studio Nội Dung.')});$('.manager-review').addEventListener('click',()=>{state.contentReviewPrefill={title,text:$('.generated-content').innerText};navigate('content-review');$('#contentReviewVideoUrl').focus();showToast('Đã chuyển nội dung sang mục Kiểm Duyệt Nội Dung. Thêm link video Drive rồi gửi quản lý.')});scrollContentResult()}
