$('#contentReviewList').addEventListener('click',async event=>{const actionButton=event.target.closest('[data-review-action]');if(actionButton){if(!isManager())return showToast('Chỉ Quản lý, Trưởng phòng hoặc Giám đốc mới có thể xét duyệt nội dung.','error');const item=state.reviews.find(review=>review.id===actionButton.dataset.id);if(!item)return;const action=actionButton.dataset.reviewAction,card=actionButton.closest('[data-review-card]'),text=String($(`[data-review-manager-text="${CSS.escape(item.id)}"]`,card)?.value||'').trim(),note=String($(`[data-review-manager-note="${CSS.escape(item.id)}"]`,card)?.value||'').trim();if(!text)return showToast('Nội dung sau kiểm duyệt không được để trống.','error');if(action==='approve'&&!driveVideoLinks(item.videoUrl)&&!reviewBridge?.attachmentValid(item))return showToast('Chưa thể phê duyệt: bài cần có link video Google Drive hợp lệ. Hãy trả bài để nhân viên bổ sung.','error');if(action==='revision'&&!note)return showToast('Ghi chú lý do cần chỉnh sửa để người gửi biết cách cập nhật.','error');const actor=reviewActor(),changed=text!==(item.text||''),historyEvent={...actor,action:action==='approve'?'approved':'revision_requested',actionLabel:action==='approve'?'Quản lý đã phê duyệt':'Quản lý yêu cầu chỉnh sửa',note};if(changed){historyEvent.beforeText=item.text||'';historyEvent.afterText=text}const updated={...item,text,status:action==='approve'?'approved':'revision_requested',reviewNote:note,reviewedBy:state.user.uid,reviewedByName:state.user.name||state.user.email,reviewedByPhoto:state.user.photoData||'',reviewedAt:actor.at,editHistory:appendContentReviewHistory(item,historyEvent)};actionButton.disabled=true;try{await saveRecord('contentReviews',updated,item.id);state.reviews=state.reviews.map(review=>review.id===item.id?updated:review);renderContentReviews();renderContentQueuePreview();showToast(action==='approve'?'Đã phê duyệt bài viết.':'Đã trả bài cho nhân viên chỉnh sửa.')}catch(error){actionButton.disabled=false;showToast(error.message||'Không lưu được quyết định duyệt.','error')}return}const resubmit=event.target.closest('[data-review-save-owner]');if(resubmit){const item=state.reviews.find(review=>review.id===resubmit.dataset.reviewSaveOwner);if(!item||item.createdBy!==state.user?.uid||!['revision_requested','rejected'].includes(item.status))return showToast('Bài viết này hiện không ở trạng thái có thể chỉnh sửa.','error');const card=resubmit.closest('[data-review-card]'),text=String($(`[data-review-owner-text="${CSS.escape(item.id)}"]`,card)?.value||'').trim(),videoUrl=String($(`[data-review-owner-video="${CSS.escape(item.id)}"]`,card)?.value||'').trim();if(!text)return showToast('Nội dung Content không được để trống.','error');if(!driveVideoLinks(videoUrl)&&!(videoUrl===''&&reviewBridge?.attachmentValid(item)))return showToast('Để trống để giữ video Final, hoặc nhập link Drive hợp lệ.','error');const actor=reviewActor(),eventLog={...actor,action:'resubmitted',actionLabel:'Nhân viên đã chỉnh sửa và gửi lại'};if(text!==(item.text||'')){eventLog.beforeText=item.text||'';eventLog.afterText=text}if(videoUrl!==(item.videoUrl||'')){eventLog.note='Đã cập nhật link video Google Drive'}const updated={...item,text,videoUrl,status:'pending',reviewNote:'',submittedAt:actor.at,editHistory:appendContentReviewHistory(item,eventLog)};if(driveVideoLinks(videoUrl)&&videoUrl!==(item.videoUrl||'')){delete updated.videoAttachment;updated.source='drive';}resubmit.disabled=true;try{await saveRecord('contentReviews',updated,item.id);state.reviews=state.reviews.map(review=>review.id===item.id?updated:review);renderContentReviews();renderContentQueuePreview();showToast('Đã lưu bản sửa và gửi lại cho quản lý.')}catch(error){resubmit.disabled=false;showToast(error.message||'Không lưu được bản sửa.','error')}}});
$('#generateContent').addEventListener('click',async()=>{const prompt=$('#contentPrompt').value.trim();if(!prompt){showToast('Nhập ý tưởng hoặc prompt trước khi tạo nội dung.','error');$('#contentPrompt').focus();return}const button=$('#generateContent'),old=button.innerHTML;button.disabled=true;button.innerHTML='✦ Đang viết…';showGeneratingContent();try{const tone=$('#contentTone').value,length=$('#contentLength').value,model=$('#contentModel').value;if(!state.firebase)throw new Error('Chưa kết nối Firebase. Hãy đăng nhập rồi thử lại.');const content=model==='gemini'?await generateGeminiContent({prompt,tone,length}):(await callFunction({openai:'generateContentOpenAI',claude:'generateContentClaude'}[model],{prompt,tone,length,model})).content;if(!String(content||'').trim())throw new Error('AI không trả về nội dung. Hãy thử prompt khác hoặc tạo lại.');const title=prompt.slice(0,42)+(prompt.length>42?'…':'');showGenerated(title,String(content).trim());if(model==='gemini'&&geminiFallbackUsed)showToast('Gemini 3.8 đang bận; nội dung đã được tạo bằng Gemini Flash-Lite dự phòng.')}catch(err){showContentGenerationError(err);showToast(err.message||'Không tạo được nội dung.','error')}finally{button.disabled=false;button.innerHTML=old}});
$('#addTemplate').addEventListener('click',()=>{
  const manager=isManager(),templateModel=$('#contentModel').value||'gemini',title=manager?'Tạo mẫu nội dung dùng chung':'Đề xuất mẫu nội dung';
  openModal(title,`<div class="modal-fields">${fInput('Tên mẫu','title','Ví dụ: Bài giới thiệu sản phẩm')}${fSelect('Giọng điệu','tone',[['Thân thiện, gần gũi','Thân thiện, gần gũi'],['Chuyên nghiệp','Chuyên nghiệp'],['Trẻ trung, năng động','Trẻ trung, năng động'],['Sang trọng, tinh tế','Sang trọng, tinh tế']])}${fSelect('Độ dài','length',[['Tiêu chuẩn','Tiêu chuẩn'],['Ngắn gọn','Ngắn gọn'],['Chi tiết','Chi tiết']])}${fSelect('Mô hình AI','model',[['gemini','Gemini'],['openai','ChatGPT'],['claude','Claude']])}<label>Prompt mẫu<textarea name="prompt" maxlength="5000" placeholder="Mô tả bố cục, thông điệp và thông tin User cần điền..." required></textarea></label></div>`,manager?'Tạo mẫu đã duyệt':'Gửi quản lý duyệt',async f=>{
    if(!state.firebase)throw new Error('Cần kết nối Firebase để lưu và chia sẻ mẫu.');
    const templateTitle=String(f.get('title')||'').trim(),prompt=String(f.get('prompt')||'').trim();
    if(!templateTitle||prompt.length<3)throw new Error('Nhập tên mẫu và prompt có ít nhất 3 ký tự.');
    const template={id:crypto.randomUUID(),title:templateTitle,prompt,text:prompt,tone:f.get('tone'),length:f.get('length'),model:f.get('model')||templateModel,status:manager?'approved':'pending',createdByName:state.user?.name||state.user?.email||'Thành viên',createdAt:new Date().toISOString()};
    await saveRecord('contentTemplates',template,template.id);state.templates.unshift(template);renderTemplates();renderContentQueuePreview();closeModal();showToast(manager?'Đã tạo mẫu chung cho User.':'Đã gửi mẫu tới quản lý duyệt.')
  });
  $('#activeModalForm [name="model"]').value=templateModel;
});

// Managers can assign tasks and change deadlines; employees can update status on their own assigned tasks.
const taskColumns=[['todo','Chưa bắt đầu'],['doing','Đang làm'],['done','Hoàn thành']];
function taskDate(d){if(!d)return'Chưa đặt';const date=d?.toDate?d.toDate():new Date(d);if(Number.isNaN(date.getTime()))return'—';return date.toLocaleDateString('vi-VN',{day:'2-digit',month:'short',year:'numeric'})+' · '+date.toLocaleTimeString('vi-VN',{hour:'2-digit',minute:'2-digit'})}
function taskDueValue(d){if(!d)return null;const date=d?.toDate?d.toDate():new Date(d);return Number.isNaN(date.getTime())?null:date}
function taskDateTimeInput(d){const date=taskDueValue(d);return date?new Date(date.getTime()-date.getTimezoneOffset()*60000).toISOString().slice(0,16):''}
function taskLocalDateKey(d){const date=taskDueValue(d);if(!date)return'';return`${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,'0')}-${String(date.getDate()).padStart(2,'0')}`}
function taskCompletionValue(task){return task.completedAt||task.updatedAt||task.createdAt}
function isTaskArchived(task,today=taskLocalDateKey(new Date())){if(task.status!=='done')return false;const completed=taskLocalDateKey(taskCompletionValue(task));return!!completed&&completed<today}
function isTaskOverdue(task,now=Date.now()){const due=taskDueValue(task.due);return task.status!=='done'&&!!due&&due.getTime()<now}
function taskDueRangeMatches(task){const from=$('#taskDueFrom')?.value||'',to=$('#taskDueTo')?.value||'';if(!from&&!to)return true;const due=taskLocalDateKey(task.due);return!!due&&(!from||due>=from)&&(!to||due<=to)}
function taskDeadlineInfo(task,now=Date.now()){const due=taskDueValue(task.due);if(!due)return{date:'Chưa đặt hạn',countdown:'Chưa có thời hạn',tone:'missing'};if(task.status==='done')return{date:taskDate(due),countdown:'Đã hoàn thành',tone:'done'};const delta=due.getTime()-now;if(delta<0){const mins=Math.max(1,Math.floor(-delta/60000));let label;if(mins<60)label=`Quá hạn ${mins} phút`;else if(mins<1440)label=`Quá hạn ${Math.floor(mins/60)} giờ ${mins%60?`${mins%60} phút`:''}`.trim();else label=`Quá hạn ${Math.floor(mins/1440)} ngày ${Math.floor(mins%1440/60)?`${Math.floor(mins%1440/60)} giờ`:''}`.trim();return{date:taskDate(due),countdown:label,tone:'overdue'}}const mins=Math.max(1,Math.ceil(delta/60000));if(mins<60)return{date:taskDate(due),countdown:`Còn ${mins} phút`,tone:'soon'};if(mins<1440)return{date:taskDate(due),countdown:`Còn ${Math.floor(mins/60)} giờ${mins%60?` ${mins%60} phút`:''}`,tone:'soon'};const days=Math.floor(mins/1440),hours=Math.floor(mins%1440/60);return{date:taskDate(due),countdown:`Còn ${days} ngày${hours?` ${hours} giờ`:''}`,tone:'normal'}}
function taskAssigneeInfo(task){const profile=state.users.find(u=>u.uid===task.assigneeUid)||(state.user?.uid===task.assigneeUid?state.user:null)||state.users.find(u=>u.name===task.assignee||u.email===task.assignee)||(state.user?.name===task.assignee?state.user:null);const name=task.assignee||profile?.name||profile?.email||'Chưa giao';const initials=profile?.initials||String(profile?.name||name).split(/\s+/).filter(Boolean).slice(-2).map(x=>x[0]).join('').toUpperCase()||task.initials||'NV';return{name,initials,photoData:profile?.photoData||task.photoData||''}}
function renderTaskArchive(){const archived=state.tasks.filter(t=>isTaskArchived(t)).sort((a,b)=>(taskLocalDateKey(taskCompletionValue(b))||'').localeCompare(taskLocalDateKey(taskCompletionValue(a))||''));const count=$('#taskArchiveCount');if(count)count.textContent=archived.length;const list=$('#taskArchiveList');if(!list||$('#taskArchivePanel')?.classList.contains('hidden'))return;const query=String($('#taskArchiveSearch')?.value||'').trim().toLocaleLowerCase('vi-VN');const rows=archived.filter(t=>!query||[t.title,t.assignee,t.tag,t.description].some(v=>String(v||'').toLocaleLowerCase('vi-VN').includes(query)));list.innerHTML=rows.length?`<div class="task-history-scroll"><div class="task-history-table"><div class="task-history-row task-history-row--head"><span>CÔNG VIỆC</span><span>NGƯỜI PHỤ TRÁCH</span><span>HẠN HOÀN THÀNH</span><span>HOÀN THÀNH LÚC</span></div>${rows.map(t=>{const person=taskAssigneeInfo(t);return`<div class="task-history-row"><span class="task-history-title"><b>${esc(t.title||'Công việc')}</b><small>${esc(t.tag||'Công việc')}</small></span><span class="task-history-person">${avatarMarkup(person.photoData,person.initials,'avatar avatar-blue task-history-avatar')}<b>${esc(person.name)}</b></span><span>${esc(taskDate(t.due))}</span><span>${esc(taskDate(taskCompletionValue(t)))}</span></div>`}).join('')}</div></div>`:'<div class="task-history-empty">'+(query?'Không tìm thấy công việc phù hợp.':'Chưa có công việc cũ đã hoàn thành.')+'</div>'}
function renderTasks(filter='all'){const assignee=$('#taskAssigneeFilter')?.value||'all';const active=state.tasks.filter(t=>!isTaskArchived(t));const visible=active.filter(t=>(assignee==='all'||t.assignee===assignee||t.assigneeUid===assignee)&&taskDueRangeMatches(t));const counts={all:visible.length,todo:visible.filter(t=>t.status==='todo').length,doing:visible.filter(t=>t.status==='doing').length,done:visible.filter(t=>t.status==='done').length,overdue:visible.filter(t=>isTaskOverdue(t)).length};for(const[key,value]of Object.entries(counts)){const el=$('#taskCount'+key[0].toUpperCase()+key.slice(1));if(el)el.textContent=value}$('#taskNavCount').textContent=state.tasks.filter(t=>t.status!=='done').length;const getTasks=status=>visible.filter(t=>t.status===status&&(filter==='all'||filter==='overdue'||filter===status)&&(filter!=='overdue'||isTaskOverdue(t))).sort((a,b)=>(taskDueValue(a.due)?.getTime()??Infinity)-(taskDueValue(b.due)?.getTime()??Infinity));$('#taskBoard').innerHTML=taskColumns.map(([status,title])=>{const tasks=getTasks(status);return`<section class="task-column task-column--${status}"><div class="task-column-head"><div><b>${title}</b><small>${status==='todo'?'Sẵn sàng bắt đầu':status==='doing'?'Đang được xử lý':'Đã bàn giao xong'}</small></div><span class="column-count">${tasks.length}</span></div><div class="task-column-list">${tasks.map(t=>{const deadline=taskDeadlineInfo(t),overdue=isTaskOverdue(t),person=taskAssigneeInfo(t);return`<article class="task-card task-card--${status}${overdue?' task-card--overdue':''}"><div class="task-card-top"><span class="task-tag">${esc(t.tag||'Công việc')}</span><span class="task-state-chip task-state-chip--${overdue?'overdue':status}">${overdue?'Quá hạn':title}</span></div><h4>${esc(t.title||'Công việc chưa đặt tên')}</h4>${t.description?`<p class="task-description">${esc(t.description)}</p>`:''}<div class="task-assignee-row">${avatarMarkup(person.photoData,person.initials,'avatar avatar-blue task-avatar')}<span class="task-assignee-copy"><small>NGƯỜI PHỤ TRÁCH</small><b>${esc(person.name)}</b></span>${t.priority==='Cao'?'<span class="priority-label">● Ưu tiên cao</span>':''}</div><div class="task-deadline task-deadline--${deadline.tone}"><span class="task-deadline-icon">◷</span><span class="task-deadline-copy"><small>HẠN HOÀN THÀNH</small><b>${esc(deadline.date)}</b></span><span class="task-deadline-meta"><span class="task-countdown">${esc(deadline.countdown)}</span>${isManager()?`<button type="button" class="task-edit-deadline" data-task-deadline="${esc(t.id)}" aria-label="Sửa hạn hoàn thành">Sửa hạn</button>`:''}</span></div><div class="task-card-actions"><span class="task-created">Giao lúc ${esc(taskDate(t.createdAt))}</span><label class="task-status-control"><span>Cập nhật trạng thái</span><select class="task-status-select task-select--${overdue?'overdue':status}" data-task-status="${esc(t.id)}" aria-label="Cập nhật trạng thái cho ${esc(t.title||'công việc')}">${taskColumns.map(([v,l])=>`<option value="${v}" ${v===status?'selected':''}>${l}</option>`).join('')}</select></label></div></article>`}).join('')||`<div class="task-empty"><span>${status==='todo'?'＋':status==='doing'?'◷':'✓'}</span><b>Chưa có công việc</b><small>${status==='todo'?'Công việc mới được giao sẽ xuất hiện ở đây.':status==='doing'?'Khi bắt đầu một việc, hãy chuyển trạng thái sang “Đang làm”.':'Các việc đã hoàn thành sẽ được lưu tại đây.'}</small></div>`}</div></section>`}).join('');const priority=active.filter(t=>t.status!=='done').sort((a,b)=>(taskDueValue(a.due)?.getTime()??Infinity)-(taskDueValue(b.due)?.getTime()??Infinity)).slice(0,3);$('#priorityTasks').innerHTML=priority.map(t=>{const person=taskAssigneeInfo(t),deadline=taskDeadlineInfo(t);return`<div class="priority-task"><span class="task-check"></span>${avatarMarkup(person.photoData,person.initials,'avatar avatar-blue priority-avatar')}<div><b>${esc(t.title)}</b><small>${esc(person.name)} · ${esc(deadline.countdown)}</small></div></div>`}).join('')||'<p class="muted">Chưa có công việc cần ưu tiên.</p>';renderTaskArchive();$$('[data-task-status]').forEach(sel=>sel.addEventListener('change',async()=>{const task=state.tasks.find(t=>t.id===sel.dataset.taskStatus);if(!task)return;if(!isManager()&&task.assigneeUid!==state.user?.uid&&task.assignee!==state.user?.name){showToast('Bạn chỉ có thể cập nhật công việc được giao cho mình.','error');sel.value=task.status;return}const old={status:task.status,completedAt:task.completedAt,updatedAt:task.updatedAt},nextStatus=sel.value,now=new Date().toISOString();task.status=nextStatus;task.completedAt=nextStatus==='done'?now:null;task.updatedAt=now;saveLocal();try{await saveRecord('tasks',task,task.id)}catch(e){Object.assign(task,old);saveLocal();renderTasks($('[data-task-filter].selected')?.dataset.taskFilter||'all');showToast(e.message,'error');return}renderTasks($('[data-task-filter].selected')?.dataset.taskFilter||'all');showToast('Đã cập nhật trạng thái công việc.')}));$$('[data-task-deadline]').forEach(button=>button.addEventListener('click',()=>{const task=state.tasks.find(item=>item.id===button.dataset.taskDeadline);if(task)openTaskDeadlineEditor(task)}))}
function openTaskDeadlineEditor(task){if(!isManager())return showToast('Chỉ Quản lý, Trưởng phòng hoặc Giám đốc mới được sửa hạn hoàn thành.','error');const currentFilter=$('[data-task-filter].selected')?.dataset.taskFilter||'all';openModal('Sửa hạn hoàn thành',`<p>Thay đổi ngày và giờ hết hạn của công việc “${esc(task.title||'Công việc')}”.</p><div class="modal-fields"><label>Thời hạn mới<input type="datetime-local" name="due" value="${taskDateTimeInput(task.due)}" required></label></div>`,'Lưu thời hạn',async form=>{if(!isManager())throw new Error('Bạn không có quyền sửa hạn hoàn thành.');const value=String(form.get('due')||'').trim();if(!taskDueValue(value))throw new Error('Hãy chọn ngày và giờ hợp lệ.');const previousDue=task.due;task.due=value;saveLocal();try{await saveRecord('tasks',task,task.id)}catch(error){task.due=previousDue;saveLocal();renderTasks(currentFilter);throw error}closeModal();renderTasks(currentFilter);showToast('Đã cập nhật hạn hoàn thành.')})}
function toggleTaskArchive(){if(!isManager())return showToast('Chỉ quản lý mới có thể xem danh sách công việc cũ.','error');const panel=$('#taskArchivePanel'),button=$('#taskArchiveToggle');if(!panel)return;panel.classList.toggle('hidden');const opened=!panel.classList.contains('hidden');if(button)button.setAttribute('aria-expanded',String(opened));renderTaskArchive();if(opened)panel.scrollIntoView({behavior:'smooth',block:'start'})}
setInterval(()=>{if($('#page-tasks')?.classList.contains('active'))renderTasks($('[data-task-filter].selected')?.dataset.taskFilter||'all')},60000);
$('#taskAssigneeFilter').addEventListener('change',()=>renderTasks($('[data-task-filter].selected')?.dataset.taskFilter||'all'));
$('#taskDueFrom').addEventListener('change',()=>renderTasks($('[data-task-filter].selected')?.dataset.taskFilter||'all'));
$('#taskDueTo').addEventListener('change',()=>renderTasks($('[data-task-filter].selected')?.dataset.taskFilter||'all'));
$('#clearTaskDueDates').addEventListener('click',()=>{$('#taskDueFrom').value='';$('#taskDueTo').value='';renderTasks($('[data-task-filter].selected')?.dataset.taskFilter||'all')});
$('#taskArchiveToggle').addEventListener('click',toggleTaskArchive);
$('#taskArchiveSearch').addEventListener('input',renderTaskArchive);
$$('[data-task-filter]').forEach(b=>b.addEventListener('click',()=>{$$('[data-task-filter]').forEach(x=>x.classList.toggle('selected',x===b));renderTasks(b.dataset.taskFilter)}));
$('#newTaskBtn').addEventListener('click',()=>{if(!isManager())return showToast('Bạn không có quyền giao công việc.','error');openModal('Giao công việc mới',`<div class="modal-fields">${fInput('Tên công việc','title','Ví dụ: Hoàn thiện báo cáo tuần')}${fInput('Mô tả','description','Mục tiêu và yêu cầu bàn giao', 'text',false)}${fSelect('Người nhận','assignee',state.members.map(m=>[m.uid,m.name]))}${fSelect('Mức ưu tiên','priority',[['Bình thường','Bình thường'],['Cao','Ưu tiên cao'],['Thấp','Thấp']])}<label>Hạn hoàn thành<input type="datetime-local" name="due" required></label>${fSelect('Phân loại','tag',[['Quảng cáo','Quảng cáo'],['Nội dung','Nội dung'],['Báo cáo','Báo cáo'],['Chatbot','Chatbot'],['Thiết kế','Thiết kế'],['Website','Website']])}</div>`,'Giao việc',async f=>{const member=state.members.find(m=>m.uid===f.get('assignee'));const assignee=member?.name||f.get('assignee'),initials=member?.initials||assignee.split(' ').map(x=>x[0]).join('').toUpperCase();const task={id:crypto.randomUUID(),title:f.get('title'),description:f.get('description'),assignee,assigneeUid:member?.uid||'',initials,tone:member?.tone||'blue',status:'todo',due:f.get('due'),priority:f.get('priority'),tag:f.get('tag'),createdAt:new Date().toISOString()};state.tasks.unshift(task);saveLocal();if(state.firebase)await saveRecord('tasks',task,task.id);closeModal();renderTasks();showToast('Đã giao công việc.')})});

function workAwardsMonthKey(date=new Date()){return`${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,'0')}`}
function workAwardsMonthBounds(monthKey){const match=/^(\d{4})-(\d{2})$/.exec(monthKey||'');if(!match)return null;const year=Number(match[1]),month=Number(match[2]);if(month<1||month>12)return null;return{start:new Date(year,month-1,1),end:new Date(year,month,1),label:new Date(year,month-1,1).toLocaleDateString('vi-VN',{month:'long',year:'numeric'})}}
function workAwardsInitials(name){return String(name||'NV').trim().split(/\s+/).filter(Boolean).slice(-2).map(part=>part[0]).join('').toLocaleUpperCase('vi-VN')||'NV'}
function workAwardsRound(value){return Math.round((Number(value)||0)*10)/10}
function calculateWorkAwards(monthKey){
  const bounds=workAwardsMonthBounds(monthKey);if(!bounds)return[];
  const profiles=(state.users.length?state.users:[state.user].filter(Boolean)).filter(user=>user&&user.approved!==false);
  const memberByUid=new Map(profiles.map(user=>[user.uid,user]));
  const byName=new Map(profiles.flatMap(user=>[[String(user.name||'').toLocaleLowerCase('vi-VN'),user],[String(user.email||'').toLocaleLowerCase('vi-VN'),user]]).filter(([name])=>name));
  const accum=new Map(profiles.map(user=>[user.uid,{uid:user.uid,name:user.name||user.email||'Thành viên',photoData:user.photoData||'',taskCount:0,lateTasks:0,lateHours:0,latePenalty:0}]));
  const monthStart=bounds.start.getTime(),monthEnd=bounds.end.getTime(),now=Date.now();
  for(const task of state.tasks){
    const due=taskDueValue(task.due);if(!due||due.getTime()<monthStart||due.getTime()>=monthEnd)continue;
    const profile=memberByUid.get(task.assigneeUid)||byName.get(String(task.assignee||'').toLocaleLowerCase('vi-VN'));if(!profile)continue;
    const row=accum.get(profile.uid);if(!row)continue;row.taskCount++;
    const completed=task.status==='done'?taskDueValue(task.completedAt||task.updatedAt||task.createdAt):null;
    const endTime=completed?completed.getTime():Math.min(now,monthEnd);
    const lateMs=Math.max(0,endTime-due.getTime());if(lateMs<=0)continue;
    const hours=lateMs/3600000;row.lateTasks++;row.lateHours+=hours;row.latePenalty+=1+hours*.5;
  }
  return[...accum.values()].map(row=>({...row,lateHours:workAwardsRound(row.lateHours),latePenalty:workAwardsRound(row.latePenalty),score:Math.max(0,workAwardsRound(10-row.latePenalty))})).sort((a,b)=>b.score-a.score||a.latePenalty-b.latePenalty||a.lateTasks-b.lateTasks||a.name.localeCompare(b.name,'vi')).map((row,index)=>({...row,rank:index+1,monthKey}));
}
function workAwardsDuration(hours){const value=workAwardsRound(hours);return`${new Intl.NumberFormat('vi-VN',{maximumFractionDigits:1}).format(value)} giờ`}
