function parseMetaMoney(value){if(value===null||value===undefined)return null;let text=String(value).replace(/[\s\u00a0]/g,'').replace(/[^\d,.-]/g,'');if(!text)return null;if(/^\d{1,3}(?:[.,]\d{3})+$/.test(text))text=text.replace(/[.,]/g,'');else if(text.includes(',')&&text.includes('.'))text=text.lastIndexOf(',')>text.lastIndexOf('.')?text.replace(/\./g,'').replace(',','.'):text.replace(/,/g,'');else if(text.includes(','))text=/,\d{3}$/.test(text)?text.replace(/,/g,''):text.replace(',','.');else if(text.includes('.'))text=/\.\d{3}$/.test(text)?text.replace(/\./g,''):text;const result=Number(text);return Number.isFinite(result)?result:null}
function monthNameVi(month){return['Tháng Một','Tháng Hai','Tháng Ba','Tháng Tư','Tháng Năm','Tháng Sáu','Tháng Bảy','Tháng Tám','Tháng Chín','Tháng Mười','Tháng Mười Một','Tháng Mười Hai'][month-1]||''}
