function downloadApprovedInvoice(id){const invoice=state.invoices.find(x=>x.id===id);if(!invoice||!(invoice.status==='approved'||!invoice.status))return showToast('Chỉ tải được hóa đơn đã được duyệt.','error');downloadFile(`hoa-don-${invoice.invoiceNumber||id}.html`,invoiceDocumentHtml(invoice),'text/html')}
function invoiceDateKey(invoice){const value=String(invoice.invoiceDate||invoice.issueDate||'');const iso=/^(\d{4}-\d{2}-\d{2})/.exec(value);if(iso)return iso[1];const localized=/^(\d{1,2})\/(\d{1,2})\/(\d{4})$/.exec(value);if(localized)return`${localized[3]}-${localized[2].padStart(2,'0')}-${localized[1].padStart(2,'0')}`;return taskLocalDateKey(invoice.createdAt)}
function currentMetaVatRange(mode){const now=new Date(),year=now.getFullYear(),month=now.getMonth(),today=taskLocalDateKey(now);if(mode==='all')return{from:'',to:'',label:'Tất cả thời gian'};if(mode==='month'){const from=`${year}-${String(month+1).padStart(2,'0')}-01`;return{from,to:today,label:`${monthNameVi(month+1)} ${year}`}}if(mode==='quarter'){const quarter=Math.floor(month/3),from=`${year}-${String(quarter*3+1).padStart(2,'0')}-01`;return{from,to:today,label:`${year}-Q${quarter+1}`}}if(mode==='year')return{from:`${year}-01-01`,to:today,label:String(year)};return{from:$('#metaVatFrom')?.value||'',to:$('#metaVatTo')?.value||'',label:'Tùy chọn'}}
function setMetaVatPreset(mode){const select=$('#metaVatPeriodMode');if(select)select.value=mode;if(mode==='all'){ $('#metaVatFrom').value='';$('#metaVatTo').value='';return}if(mode==='custom')return;const range=currentMetaVatRange(mode);$('#metaVatFrom').value=range.from;$('#metaVatTo').value=range.to}
function downloadBlobFile(fileName,blob){const url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=fileName;document.body.append(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),60000)}
function metaVatInvoicesVisible(){return state.invoices.filter(invoice=>invoice.documentType==='meta_ads'&&(isManager()||invoice.createdBy===state.user?.uid))}
function metaVatUsers(invoices){const users=new Map();for(const user of state.users||[]){if(user.uid)users.set(user.uid,{uid:user.uid,name:user.name||user.email||'Tài khoản',email:user.email||'',department:user.department||''})}for(const invoice of invoices){if(invoice.createdBy&&!users.has(invoice.createdBy))users.set(invoice.createdBy,{uid:invoice.createdBy,name:invoice.createdByName||invoice.employeeName||'Nhân viên',email:'',department:invoice.department||''})}return[...users.values()].sort((a,b)=>a.name.localeCompare(b.name,'vi'))}
function exportMetaVatCsv(){const mode=$('#metaVatPeriodMode')?.value||'custom',range=currentMetaVatRange(mode),userId=isManager()?($('#metaVatUser')?.value||'all'):state.user?.uid,rows=metaVatInvoicesVisible().filter(invoice=>{const date=invoiceDateKey(invoice);return(!range.from||date>=range.from)&&(!range.to||date<=range.to)&&(userId==='all'||invoice.createdBy===userId)});const cells=[['Kỳ thuế','Nhân sự','Phòng ban','Ngày hóa đơn','Nhà cung cấp','Mã hóa đơn','ID giao dịch','Trước VAT','VAT','Tổng thanh toán','Trạng thái','Tệp PDF'],...rows.map(invoice=>[invoice.taxPeriod,invoice.createdByName,invoice.department,invoice.invoiceDate,invoice.supplier,invoice.invoiceNumber,invoice.transactionIds,invoice.amountBeforeVat,invoice.vatAmount,invoice.total,invoiceStatus(invoice.status)[0],invoice.pdfFileName])];const csv='\ufeff'+cells.map(row=>row.map(value=>'"'+String(value??'').replace(/"/g,'""')+'"').join(',')).join('\r\n');downloadBlobFile(`bao-cao-vat-meta-${new Date().toISOString().slice(0,10)}.csv`,new Blob([csv],{type:'text/csv;charset=utf-8'}))}
function renderMetaVatReport(){const body=$('#metaVatTable');if(!body)return;const period=$('#metaVatPeriodMode');if(period&&!period.dataset.initialized){const range=currentMetaVatRange('quarter');period.value='custom';period.dataset.initialized='true';$('#metaVatFrom').value=range.from;$('#metaVatTo').value=range.to}const allMeta=metaVatInvoicesVisible(),users=metaVatUsers(allMeta),userSelect=$('#metaVatUser'),selectedUser=userSelect?.value||(isManager()?'all':state.user?.uid||'');if(userSelect){if(isManager()){userSelect.innerHTML='<option value="all">Tất cả hóa đơn</option>'+users.map(user=>`<option value="${esc(user.uid)}">${esc(user.name)}${user.department?` · ${esc(user.department)}`:''}</option>`).join('');userSelect.disabled=false;userSelect.value=selectedUser==='all'||users.some(user=>user.uid===selectedUser)?selectedUser:'all'}else{const ownUid=state.user?.uid||'';userSelect.innerHTML=`<option value="${esc(ownUid)}">Hóa đơn của tôi</option>`;userSelect.value=ownUid;userSelect.disabled=true}}const userId=isManager()?(userSelect?.value||'all'):state.user?.uid||'',userName=userId==='all'?'Tất cả hóa đơn':isManager()?(users.find(user=>user.uid===userId)?.name||'Nhân sự'):'Hóa đơn của tôi',mode=period?.value||'custom',range=currentMetaVatRange(mode),rows=allMeta.filter(invoice=>{const date=invoiceDateKey(invoice);return(!range.from||date>=range.from)&&(!range.to||date<=range.to)&&(userId==='all'||invoice.createdBy===userId)}).sort((a,b)=>invoiceDateKey(b).localeCompare(invoiceDateKey(a)));const sum=field=>rows.reduce((total,invoice)=>total+(Number(invoice[field])||0),0);$('#metaVatPeriodLabel').textContent=`${range.label}${range.from&&range.to?` · ${range.from} – ${range.to}`:''} · ${rows.length} hóa đơn · ${userName}`;$('#metaVatSubtotal').textContent=money(sum('amountBeforeVat'));$('#metaVatVatTotal').textContent=money(sum('vatAmount'));$('#metaVatGrandTotal').textContent=money(sum('total'));$('#metaVatCountAll').textContent=rows.length;$('#metaVatCountPending').textContent=rows.filter(invoice=>invoice.status==='pending').length;$('#metaVatCountApproved').textContent=rows.filter(invoice=>invoice.status==='approved').length;$('#metaVatCountRejected').textContent=rows.filter(invoice=>invoice.status==='rejected').length;body.innerHTML=rows.map(invoice=>{const status=invoiceStatus(invoice.status),actions=`${invoice.attachmentChunkCount?`<button class="text-button" data-meta-invoice-pdf="${esc(invoice.id)}">PDF</button>`:''}${isManager()&&invoice.status==='pending'?`<span class="vat-row-review"><button class="approve-btn" data-vat-action="approved" data-id="${esc(invoice.id)}">Duyệt</button><button class="reject-btn" data-vat-action="rejected" data-id="${esc(invoice.id)}">Từ chối</button></span>`:''}`;return`<tr><td>${esc(invoice.taxPeriod||'—')}</td><td>${esc(invoice.createdByName||invoice.employeeName||'Nhân viên')}<small>${esc(invoice.department||'')}</small></td><td>${esc(invoiceDateKey(invoice)||'—')}</td><td>${esc(invoice.transactionIds||'—')}</td><td>${money(invoice.amountBeforeVat)}</td><td>${money(invoice.vatAmount)}</td><td><b>${money(invoice.total)}</b></td><td><span class="status ${status[1]}">${status[0]}</span></td><td>${actions||'—'}</td></tr>`}).join('')||'<tr><td colspan="9" class="muted">Không có hóa đơn trong bộ lọc này.</td></tr>';$$('[data-meta-invoice-pdf]').forEach(button=>button.addEventListener('click',()=>downloadMetaInvoicePdf(button.dataset.metaInvoicePdf)));$$('[data-vat-action]').forEach(button=>button.addEventListener('click',()=>updateInvoiceStatus(button.dataset.id,button.dataset.vatAction)))}
$('#metaVatPeriodMode').addEventListener('change',()=>{setMetaVatPreset($('#metaVatPeriodMode').value);renderMetaVatReport()});$('#metaVatFrom').addEventListener('change',()=>{if($('#metaVatPeriodMode').value!=='all')$('#metaVatPeriodMode').value='custom';renderMetaVatReport()});$('#metaVatTo').addEventListener('change',()=>{if($('#metaVatPeriodMode').value!=='all')$('#metaVatPeriodMode').value='custom';renderMetaVatReport()});$('#metaVatUser').addEventListener('change',renderMetaVatReport);$('#clearMetaVatFilters').addEventListener('click',()=>{setMetaVatPreset('quarter');if($('#metaVatUser'))$('#metaVatUser').value=isManager()?'all':state.user?.uid||'';renderMetaVatReport()});$('#exportMetaVatCsv').addEventListener('click',exportMetaVatCsv);
function renderInvoices(){const body=$('#invoiceTable');if(!body){renderMetaVatReport();return}const rows=[...state.invoices].sort((a,b)=>String(b.createdAt||'').localeCompare(String(a.createdAt||'')));body.innerHTML=rows.map(invoice=>{const status=invoice.status||'approved',label=invoiceStatus(status),date=invoice.createdAt?.toDate?invoice.createdAt.toDate().toLocaleDateString('vi-VN'):invoice.createdAt?new Date(invoice.createdAt).toLocaleDateString('vi-VN'):'—';const fileAction=invoice.attachmentChunkCount?`<button class="text-button" data-invoice-pdf="${esc(invoice.id)}">Xem PDF</button>`:'';const approval=isManager()&&status==='pending'?`<button class="approve-btn" data-invoice-action="approved" data-id="${esc(invoice.id)}">Duyệt</button><button class="reject-btn" data-invoice-action="rejected" data-id="${esc(invoice.id)}">Từ chối</button>`:'';const action=invoice.documentType==='meta_ads'?`${fileAction}${approval||(!fileAction?'—':'')}`:status==='approved'||!invoice.status?`<button class="text-button" data-invoice-download="${esc(invoice.id)}">Tải hóa đơn</button>`:approval||'—';const title=invoice.documentType==='meta_ads'?invoice.metaInvoiceNumber||invoice.invoiceNumber:invoice.invoiceNumber||'Đề xuất';return`<tr><td><b>${esc(title)}</b><small>${esc(invoice.documentType==='meta_ads'?invoice.supplier:invoice.customer||'')}</small></td><td>${esc(invoice.documentType==='meta_ads'?'Meta/Facebook Ads':invoice.item||'—')}<small>${invoice.documentType==='meta_ads'?`${esc(invoice.invoiceDate||'')} · ${esc(invoice.taxPeriod||'')}`:`${Number(invoice.quantity)||0} × ${money(invoice.unitPrice??invoice.price)}`}</small></td><td>${money(invoice.total)}</td><td>${esc(invoice.createdByName||invoice.employee||'Nhân viên')}<small>${esc(date)}</small></td><td><span class="status ${label[1]}">${label[0]}</span></td><td>${action}</td></tr>`}).join('')||'<tr><td colspan="6" class="muted">Chưa có đề xuất hóa đơn.</td></tr>';const pending=state.invoices.filter(invoice=>invoice.status==='pending').length;$('#invoicePendingCount').textContent=pending+' chờ duyệt';$$('[data-invoice-download]').forEach(button=>button.addEventListener('click',()=>downloadApprovedInvoice(button.dataset.invoiceDownload)));$$('[data-invoice-pdf]').forEach(button=>button.addEventListener('click',()=>downloadMetaInvoicePdf(button.dataset.invoicePdf)));$$('[data-invoice-action]').forEach(button=>button.addEventListener('click',()=>updateInvoiceStatus(button.dataset.id,button.dataset.invoiceAction)));renderMetaVatReport()}
async function updateInvoiceStatus(id,status,note=''){if(!isManager()){showToast('Chỉ trưởng phòng hoặc quản lý mới có thể duyệt hóa đơn.','error');return false}const invoice=state.invoices.find(x=>x.id===id);if(!invoice||invoice.status!=='pending')return false;try{const reviewed={...invoice,status,reviewNote:String(note||'').trim(),reviewedBy:state.user.uid,reviewedByName:state.user.name,reviewedByPhoto:state.user.photoData||'',reviewedAt:new Date().toISOString()};await saveRecord('invoices',reviewed,id);state.invoices=state.invoices.map(x=>x.id===id?reviewed:x);saveLocal();renderInvoices();showToast(status==='approved'?'Đã duyệt đề xuất hóa đơn.':'Đã từ chối đề xuất hóa đơn.');if($('#modalRoot').innerHTML){closeModal();openInvoiceQueue()}return true}catch(e){showToast(e.message||'Không thể cập nhật hóa đơn.','error');return false}}
async function openInvoiceQueue(){if(!isManager())return showToast('Chỉ trưởng phòng hoặc quản lý mới có thể duyệt hóa đơn.','error');if(state.firebase){try{const snapshot=await state.firebase.storeMod.getDocs(state.firebase.storeMod.collection(state.firebase.db,'workspaces','fbtq','invoices'));state.invoices=snapshot.docs.map(d=>({id:d.id,...d.data()}));renderInvoices()}catch(e){return showToast(e.message,'error')}}const pending=state.invoices.filter(x=>x.status==='pending');const rows=pending.map(invoice=>`<div class="request-row invoice-review-row"><span class="template-icon ti-green">▧</span><div><b>${esc(invoice.invoiceNumber||'Đề xuất hóa đơn')} · ${esc(invoice.documentType==='meta_ads'?invoice.supplier:invoice.customer||'')}</b><small>${invoice.documentType==='meta_ads'?`ID giao dịch ${esc(invoice.transactionIds||'—')} · Trước VAT ${money(invoice.amountBeforeVat)} · VAT ${money(invoice.vatAmount)} · Tổng ${money(invoice.total)}`:`${esc(invoice.item||'')} · ${money(invoice.total)}`} · ${esc(invoice.createdByName||invoice.employee||'Nhân viên')}</small></div>${invoice.attachmentChunkCount?`<button type="button" class="text-button" data-queue-invoice-pdf="${esc(invoice.id)}">Xem PDF</button>`:''}<button type="button" class="approve-btn" data-invoice-queue="approved" data-id="${esc(invoice.id)}">Duyệt</button><button type="button" class="reject-btn" data-invoice-queue="rejected" data-id="${esc(invoice.id)}">Từ chối</button></div>`).join('')||'<p class="muted">Không có hóa đơn nào chờ duyệt.</p>';openModal('Đề xuất hóa đơn',`<p>Kiểm tra thông tin trước khi phê duyệt hoặc từ chối.</p>${rows}`,'',null);$$('[data-invoice-queue]').forEach(button=>button.addEventListener('click',()=>updateInvoiceStatus(button.dataset.id,button.dataset.invoiceQueue)));$$('[data-queue-invoice-pdf]').forEach(button=>button.addEventListener('click',()=>downloadMetaInvoicePdf(button.dataset.queueInvoicePdf)))}
// Chatbot integrations.
$('#botToggle').addEventListener('click',()=>showToast('AI chỉ tạo gợi ý; nhân viên xác nhận trước khi gửi.'));
async function sendChatReply(text){if(!state.firebase||!state.activeThread)return showToast('Kết nối Fanpage và chọn hội thoại.','error');const thread={...state.activeThread},requestId=crypto.randomUUID();openModal('Xác nhận trả lời — '+(thread.senderName||thread.senderId),'<div class="modal-fields"><label>Tin nhắn<textarea name="message" required maxlength="2000">'+esc(text)+'</textarea></label></div>','Gửi tin nhắn',async f=>{await callFunction('sendChatbotMessage',{pageId:thread.pageId,recipientId:thread.senderId,message:f.get('message'),requestId});$('#replyInput').value='';closeModal();showToast('Đã gửi tin nhắn.');});}
$('#sendReply').addEventListener('click',async()=>{const text=$('#replyInput').value.trim();if(!text)return;await sendChatReply(text)});$('#replyInput').addEventListener('keydown',e=>{if(e.key==='Enter')$('#sendReply').click()});
function editScripts(){if(!isManager())return showToast('Chỉ quản lý mới có thể chỉnh kịch bản.','error');const content=state.scripts.map((s,i)=>`<div class="draft-row"><span class="template-icon ti-blue">▧</span><div><b>${esc(s.title)}</b><small>${esc(s.text)}</small>${s.image?`<small>✓ Đã đính kèm hình ảnh</small>`:''}</div><button type="button" data-edit-script="${i}">Sửa</button></div>`).join('');openModal('Kịch bản phản hồi',`<p>Quản lý câu trả lời nhanh đã được duyệt. Có thể gắn kịch bản vào Fanpage.</p><div class="draft-list">${content||'Chưa có kịch bản.'}</div><button type="button" class="btn btn-secondary" id="newScript" style="margin-top:12px">＋ Thêm kịch bản</button>`,'',null);$('#newScript').addEventListener('click',()=>editScriptForm());$$('[data-edit-script]').forEach(b=>b.addEventListener('click',()=>editScriptForm(Number(b.dataset.editScript))))}
function editScriptForm(index=null){const item=index===null?{title:'',text:''}:state.scripts[index];openModal(index===null?'Thêm kịch bản':'Sửa kịch bản',`<div class="modal-fields">${fInput('Tên kịch bản','title','Ví dụ: Chào khách mới')}<label>Nội dung trả lời<textarea name="text" required>${esc(item.text)}</textarea></label><label>Hình ảnh (tuỳ chọn)<input type="file" name="imageFile" accept="image/*"></label><img id="scriptPreview" class="${item.image?'':'hidden'}" src="${esc(item.image||'')}" style="max-width:100px;border-radius:7px"></div>`,'Lưu kịch bản',async f=>{const file=$('[name=imageFile]').files[0];let image=item.image||'';if(file)image=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=reject;reader.readAsDataURL(file)});const next={title:f.get('title'),text:f.get('text'),image};if(index===null)state.scripts.push(next);else state.scripts[index]=next;saveLocal();if(state.firebase)await saveRecord('settings',{scripts:state.scripts},'bot');closeModal();editScripts();showToast('Đã lưu kịch bản.')});$('[name=imageFile]')?.addEventListener('change',e=>{const f=e.target.files[0];if(f){const img=$('#scriptPreview');img.src=URL.createObjectURL(f);img.classList.remove('hidden')}})}
function editBanned(){if(!isManager())return showToast('Chỉ quản lý mới có thể chỉnh từ khoá cấm.','error');openModal('Từ khoá cấm',`<p>Mỗi dòng là một cụm từ. Công cụ kiểm duyệt sẽ cảnh báo khi nội dung gửi duyệt có chứa các từ/cụm này.</p><div class="modal-fields"><label>Từ khoá<textarea name="words">${esc(state.banned.join('\n'))}</textarea></label></div>`,'Lưu từ khoá',async f=>{state.banned=f.get('words').split(/\r?\n/).map(x=>x.trim()).filter(Boolean);saveLocal();if(state.firebase)await saveRecord('settings',{banned:state.banned},'bot');renderBotSummaries();updateContentReviewInput(false);renderContentReviews();closeModal();showToast('Đã cập nhật danh sách từ khoá.')})}
$('#manageScripts').addEventListener('click',editScripts);$('#editScripts').addEventListener('click',editScripts);$('#manageBanned').addEventListener('click',editBanned);$('#editBanned').addEventListener('click',editBanned);
function renderBotSummaries(){const bannedText=state.banned.length+' từ khoá',scriptText=state.scripts.length+' kịch bản'+(state.scripts.some(item=>item.image)?' · có hình ảnh':'');['#bannedSummary','#settingsBannedSummary'].forEach(selector=>{const el=$(selector);if(el)el.textContent=bannedText});['#scriptSummary','#settingsScriptSummary'].forEach(selector=>{const el=$(selector);if(el)el.textContent=scriptText})}
function renderConnectedPages(){const list=$('#connectedPages');if(!list)return;list.innerHTML=state.pages.map(page=>`<span class="page-connection"><i class="fb-round">f</i><span><b>${esc(page.pageName)}</b><small>${page.active?'Đang hoạt động':'Tạm dừng'}</small></span><span class="${page.active?'live-dot':'status status-neutral'}"></span></span>`).join('')||'<p class="muted">Chưa có Fanpage được kết nối.</p>'}
function connectPage(){chatbotWorkspace.openSetup();}
function connectPageAdvanced(){if(!state.firebase)return showToast('Cần đăng nhập Firebase trước khi kết nối Fanpage.','error');openModal('Kết nối Fanpage',`<p>Nhập Page ID và Page Access Token. Token sẽ được gửi qua HTTPS, mã hoá trên máy chủ trước khi lưu.</p><div class="modal-fields">${fInput('Tên Fanpage','pageName','Tên trang')}${fInput('Facebook Page ID','pageId','ID trang quảng cáo')}${fInput('Page Access Token','pageToken','Page token','password')}${fSelect('Mô hình AI','model',[['gemini','Gemini'],['openai','ChatGPT']])}</div>`,'Kết nối',async f=>{const result=await callFunction('connectFacebookPage',{pageName:f.get('pageName'),pageId:f.get('pageId'),pageToken:f.get('pageToken'),model:f.get('model')});state.pages=[...state.pages.filter(p=>p.pageId!==f.get('pageId')),{pageId:f.get('pageId'),pageName:result.pageName||f.get('pageName'),model:f.get('model'),active:true}];renderConnectedPages();closeModal();showToast(result.message||'Đã kết nối Fanpage.')})}
$('#connectPage').addEventListener('click',connectPage);$('#settingsConnectPage').addEventListener('click',connectPage);$('#addPageInline').addEventListener('click',connectPage);

// Access control and user invitations.
$('#inviteUser').addEventListener('click',()=>{if(!isDirector())return showToast('Chỉ Giám đốc mới có thể mời thành viên.','error');openModal('Mời thành viên',`<p>Gửi lời mời để thành viên đăng ký bằng email công ty. Phân quyền có thể thay đổi sau khi tài khoản được xác minh.</p><div class="modal-fields">${fInput('Email công việc','email','ten@fbtq.vn','email')}${fSelect('Vai trò dự kiến','role',Object.entries(ROLE_NAMES).map(([k,v])=>[k,v]))}${fSelect('Phòng ban','department',[['Marketing','Marketing'],['Kinh doanh','Kinh doanh'],['Vận hành','Vận hành']])}</div>`,'Tạo lời mời',async f=>{const invite={email:f.get('email'),role:f.get('role'),department:f.get('department'),status:'invited',invitedBy:state.user?.uid};if(state.firebase)await saveRecord('invitations',invite);closeModal();showToast('Đã tạo lời mời. Chia sẻ liên kết đăng ký với thành viên.')})});
$('#editPermissions').addEventListener('click',()=>{if(!isDirector())return showToast('Chỉ Giám đốc mới có thể chỉnh phân quyền.','error');openModal('Phân quyền & vai trò',`<p>Nhập UID lấy trong Firebase Authentication hoặc email của tài khoản đã đăng ký. Vai trò được lưu trong Firestore và được Security Rules kiểm tra; thành viên cần đăng xuất rồi đăng nhập lại để tải quyền mới.</p><div class="modal-fields">${fInput('UID hoặc email tài khoản','uidOrEmail','Dán UID hoặc nhập email','text')}${fSelect('Vai trò mới','role',Object.entries(ROLE_NAMES).map(([k,v])=>[k,v]))}</div>`,'Cập nhật quyền',async f=>{try{const identifier=String(f.get('uidOrEmail')||'').trim(),role=f.get('role');if(!identifier||!state.firebase)throw new Error('Nhập UID/email và kết nối Firebase trước.');const {db,storeMod:s}=state.firebase;let member=state.users.find(item=>item.uid===identifier||String(item.email||'').toLowerCase()===identifier.toLowerCase());if(!member){if(identifier.includes('@')){const result=await s.getDocs(s.query(s.collection(db,'users'),s.where('email','==',identifier.toLowerCase())));const snap=result.docs[0];if(snap)member={uid:snap.id,...snap.data()}}else{const ref=s.doc(db,'users',identifier),snap=await s.getDoc(ref);if(snap.exists())member={uid:snap.id,...snap.data()}}}if(!member)throw new Error('Không tìm thấy hồ sơ Firestore của tài khoản. Thành viên cần đăng ký và đăng nhập website ít nhất một lần.');await s.updateDoc(s.doc(db,'users',member.uid),{role,approved:true,updatedAt:s.serverTimestamp(),updatedBy:state.user.uid});state.users=state.users.map(item=>item.uid===member.uid?{...item,role,approved:true}:item);closeModal();showToast(`Đã gán quyền ${roleName(role)}. Thành viên cần đăng xuất rồi đăng nhập lại.`)}catch(e){showToast(e.message||'Không thể cập nhật vai trò.','error')}})});
$('#metaConnect').addEventListener('click',()=>{navigate('settings');selectSetting('chatbot');showToast('Thiết lập Meta App trong mục Chatbot & Fanpage.')});

// Firebase and model settings.
$('#saveFirebase').addEventListener('click',async()=>{const c=configFromInputs();if(!validConfig(c)){showToast('Hãy điền đủ Firebase API Key, Auth Domain, Project ID và App ID.','error');return}localStorage.setItem('fbtq_firebase_config',JSON.stringify(c));if(state.firebase){showToast('Đã lưu cấu hình. Tải lại trang để áp dụng App Check và AI Logic.');return}firebaseBootPromise=firebaseInit(c,true);const ok=await firebaseBootPromise;if(ok&&window.location.protocol==='file:')showToast('Mở website qua HTTPS để Firebase Auth hoạt động.','error')});
$('#disconnectFirebase').addEventListener('click',async()=>{if(state.firebase)await state.firebase.authMod.signOut(state.firebase.auth);signOutToAuth();showToast('Đã đăng xuất khỏi workspace.')});
$('#saveAiSettings').addEventListener('click',async()=>{if(!isManager())return showToast('Chỉ quản lý mới có thể cấu hình mô hình AI.','error');const config={defaultModel:$('#defaultModel').value,brandVoice:$('#brandVoice').value};localStorage.setItem('fbtq_default_model',config.defaultModel);localStorage.setItem('fbtq_brand_voice',config.brandVoice);if(state.firebase)try{await saveRecord('settings',config,'bot')}catch(e){showToast(e.message,'error');return}$('#contentModel').value=config.defaultModel;$('#aiConfigStatus').textContent='Gemini dùng Firebase AI Logic; OpenAI và Claude dùng Cloud Functions.';showToast('Đã lưu cấu hình nội dung.')});
$('#enableAutoReply').addEventListener('change',e=>showToast(e.target.checked?'Đã bật chế độ AI đề xuất. Nhân viên cần xác nhận trước khi gửi.':'Đã tắt AI đề xuất.'));

// Small utilities and initial setup.
$('#notificationBtn').addEventListener('click',()=>{const panel=$('#systemNotificationPanel'),button=$('#notificationBtn'),open=panel.classList.contains('hidden');if(open){renderSystemNotifications();panel.classList.remove('hidden');button.setAttribute('aria-expanded','true')}else{panel.classList.add('hidden');button.setAttribute('aria-expanded','false')}});
$('#markNotificationsRead').addEventListener('click',event=>{event.stopPropagation();markSystemNotificationsRead()});
$('#closeSystemNotifications').addEventListener('click',()=>{$('#systemNotificationPanel').classList.add('hidden');$('#notificationBtn').setAttribute('aria-expanded','false')});
$('#systemNotificationList').addEventListener('click',event=>{const itemButton=event.target.closest('[data-system-notification]');if(!itemButton)return;const read=notificationReadSet();read.add(itemButton.dataset.systemNotification);saveNotificationReadSet(read);renderSystemNotifications();$('#systemNotificationPanel').classList.add('hidden');$('#notificationBtn').setAttribute('aria-expanded','false');navigate(itemButton.dataset.notificationPage)});
document.addEventListener('click',event=>{if(!event.target.closest('.notification-area')){$('#systemNotificationPanel').classList.add('hidden');$('#notificationBtn').setAttribute('aria-expanded','false')}});
window.addEventListener('keydown',event=>{if(event.key==='Escape'&&!$('#systemNotificationPanel').classList.contains('hidden')){$('#systemNotificationPanel').classList.add('hidden');$('#notificationBtn').setAttribute('aria-expanded','false')}});
$('#topProfile').addEventListener('click',openProfileDialog);
$('#copyGuide')?.setAttribute('aria-label','Hướng dẫn sao chép chỉ số Facebook Ads');
const savedFirebase=getSavedFirebaseConfig()||window.FBTQ_FIREBASE_CONFIG;if(validConfig(savedFirebase)){['apiKey','authDomain','projectId','appId','appCheckSiteKey'].forEach(k=>{const el=$('#fb'+k[0].toUpperCase()+k.slice(1));if(el)el.value=savedFirebase[k]||''});firebaseBootPromise=firebaseInit(savedFirebase)}
$('#defaultModel').value=localStorage.getItem('fbtq_default_model')||'gemini';$('#brandVoice').value=localStorage.getItem('fbtq_brand_voice')||'';const bootModel=$('#defaultModel').value;$('#contentModel').value=['gemini','openai','claude'].includes(bootModel)?bootModel:'gemini';

workflows = initWorkflows({state, $, esc, money, avatarMarkup, openModal, closeModal, showToast, callFunction, roleName, onDataChange:renderSystemNotifications});
overviewHub=initOverviewHub({state,$,esc,money,avatarMarkup,navigate,getWorkflow:()=>workflows?.assistantData?.()||{}});renderOverviewOperations();
const billingTabsMarkup='<nav class="work-section-tabs billing-section-tabs" aria-label="Báo cáo hoá đơn"><button type="button" class="selected" data-billing-tab="advances"><span>₫</span>Hoá Đơn Tạm Ứng</button><button type="button" data-billing-tab="automation"><span>▤</span>Báo Cáo Hoá Đơn Chi Tiêu</button></nav>';
$('#page-advances')?.insertAdjacentHTML('afterbegin',billingTabsMarkup);
$('#page-automation')?.insertAdjacentHTML('afterbegin',billingTabsMarkup);
$$('[data-billing-tab]').forEach(button=>button.addEventListener('click',()=>navigate(button.dataset.billingTab)));

function restoreAssistantHistory(messages,more){
  fbtqPendingConfirmation=null;
  for(const selector of ['#assistantMessages','#fbtqAssistantMessages']){const list=$(selector);if(!list)continue;list.replaceChildren();if(!messages.length)appendFbtqAssistantMessage('assistant','Xin chào! Bạn có thể nhập số liệu, hóa đơn, tra cứu và mở các chức năng hệ thống. Mọi thay đổi cần bạn phê duyệt trước khi thực hiện.',[],list,false);else for(const message of messages)appendFbtqAssistantMessage(message.role,message.text,[],list,false);}
  for(const button of $$('[data-assistant-history-older]'))button.hidden=!more;
}
assistantHistory=createAssistantHistory({getUser:()=>state.user,getFirebase:()=>state.firebase,onRestore:restoreAssistantHistory,onStatus:text=>{$$('[data-assistant-history-status]').forEach(el=>el.textContent=text);}});
actionApproval=initActionApproval({getUser:()=>state.user,esc,onLog:text=>appendFbtqAssistantMessage('assistant',text),onError:message=>showToast(message,'error')});
$$('[data-assistant-history-older]').forEach(button=>button.addEventListener('click',()=>assistantHistory.loadOlder()));
$('#assistantExpandWorkspace')?.addEventListener('click',()=>{setFbtqAssistantWindow(false);navigate('assistant');});
$('#fbtqAssistantExpand')?.addEventListener('click',()=>{const panel=$('#fbtqAssistantWindow'),expanded=panel.classList.toggle('is-expanded');$('#fbtqAssistantExpand').setAttribute('aria-expanded',String(expanded));});
for(const id of ['dailyCompareA','dailyCompareB']){const input=$('#'+id);if(input){input.max=vnToday();if(!input.value){const today=new Date(vnToday()+'T00:00:00Z');if(id==='dailyCompareA')today.setUTCDate(today.getUTCDate()-1);input.value=today.toISOString().slice(0,10);}input.addEventListener('change',renderDailyReportComparison);}}

let lastDailyBoundary=vnToday();
function refreshDailyBoundary(){const day=vnToday();if(day===lastDailyBoundary)return;lastDailyBoundary=day;const input=$('#modalRoot [name="reportDate"]');if(input){input.max=day;const status=$('#dailySheetCsvStatus');if(status)status.textContent='Đã sang ngày '+day+'. Bấm Hôm nay để mở báo cáo ngày mới. Dữ liệu chưa lưu đang được giữ để bạn kiểm tra.';}for(const id of ['dailyCompareA','dailyCompareB'])if($('#'+id))$('#'+id).max=day;}
setInterval(refreshDailyBoundary,60000);window.addEventListener('focus',refreshDailyBoundary);

reviewBridge=createFinalReviewBridge({state,navigate,toast:showToast,onPreviewChanged:()=>updateContentReviewInput()});
const creativeStudio=initCreativeStudio({state,showToast,onFinal:artifact=>reviewBridge.stage(artifact)});
const chatbotWorkspace=initChatbotWorkspace({state,callFunction,openModal,closeModal,esc,showToast,connectPageAdvanced,renderConnectedPages});

for(const container of [$('#fbtqAssistantWindow .fbtq-dock-head'),$('#page-assistant .page-heading')].filter(Boolean)){
 const label=document.createElement('label');label.className='assistant-model-picker';label.innerHTML='<span>Mô hình AI</span><select aria-label="Mô hình Trợ lý FBTQ"><option value="gemini">Gemini</option><option value="openai">OpenAI</option><option value="claude">Claude</option></select>';container.append(label);const select=label.querySelector('select');select.value=localStorage.getItem('fbtq_assistant_provider')||'gemini';select.onchange=()=>{localStorage.setItem('fbtq_assistant_provider',select.value);document.querySelectorAll('.assistant-model-picker select').forEach(el=>el.value=select.value);};
}

const peopleRetry=document.createElement('button');peopleRetry.type='button';peopleRetry.className='btn btn-secondary';peopleRetry.id='reloadPeople';peopleRetry.textContent='↻ Tải lại user';$('#page-people .page-heading')?.append(peopleRetry);peopleRetry.onclick=async()=>{peopleRetry.disabled=true;try{if(!state.firebase||!isManager())return showToast('Đăng nhập tài khoản quản lý để tải user.','error');const uid=state.user.uid;await loadIndependentCollections({state,uid,reads:[{key:'users',idField:'uid',load:()=>state.firebase.storeMod.getDocs(state.firebase.storeMod.collection(state.firebase.db,'users'))}]});if(state.user?.uid!==uid)return;state.members=state.users.filter(m=>m.approved!==false).map(m=>({uid:m.uid,name:m.name||m.email,initials:(m.name||m.email||'NV').split(/\s+/).slice(-2).map(w=>w[0]).join(''),photoData:m.photoData||'',tone:'blue'}));renderPeople();showToast(state.usersLoadError?'Chưa tải được user: '+state.usersLoadError:'Đã tải '+state.users.length+' tài khoản.',state.usersLoadError?'error':undefined);}finally{peopleRetry.disabled=false;}};
